	-- ===== helpers =====
	local function flat(v)
		local f = Vector3.new(v.X, 0, v.Z)
		if f.Magnitude < 1e-3 then return Vector3.new(0, 0, -1) end
		return f.Unit
	end

	local function sfx(id, parent, volume)
		if not PLAY_SOUNDS then return end
		local s = Instance.new("Sound")
		s.SoundId = "rbxassetid://" .. tostring(id)
		s.Volume = volume or 0.5
		s.RollOffMaxDistance = 150
		s.Parent = parent or workspace
		s:Play()
		s.Ended:Connect(function() s:Destroy() end)
		Debris:AddItem(s, 15)
	end

	-- ===== animation data =====
	local function compile(src)
		local out = {}
		for name, a in pairs(src) do
			local c = { L = a.L, Loop = a.Loop, tr = {} }
			for key, s in pairs(a) do
				if type(s) == "string" then
					local tr = {}
					for row in s:gmatch("[^;]+") do
						local f = {}
						for v in row:gmatch("[^,]+") do f[#f + 1] = tonumber(v) end
						tr[#tr + 1] = { t = f[1], cf = CFrame.new(f[2], f[3], f[4], f[5], f[6], f[7], f[8]) }
					end
					c.tr[key] = tr
				end
			end
			out[name] = c
		end
		return out
	end

	local function sample(tr, t)
		local n = #tr
		if n == 1 or t <= tr[1].t then return tr[1].cf end
		if t >= tr[n].t then return tr[n].cf end
		local lo, hi = 1, n
		while hi - lo > 1 do
			local mid = (lo + hi) // 2
			if tr[mid].t <= t then lo = mid else hi = mid end
		end
		local a, b = tr[lo], tr[hi]
		return a.cf:Lerp(b.cf, (t - a.t) / (b.t - a.t))
	end

	-- ===== walk speed lock (TSB owns WalkSpeed, so this is best effort) =====
	local function lockMove()
		if not hum then return end
		if not S.ws0 then S.ws0 = hum.WalkSpeed end
		hum.WalkSpeed = 0
	end

	local function unlockMove()
		if hum and S.ws0 then hum.WalkSpeed = S.ws0 end
		S.ws0 = nil
	end

	-- ===== one-shot animation layer =====
	-- o: rate, loop, onEnd, events = { {seconds (animation time), fn}, ... }, data, fadeIn, fadeOut
	local function playAct(name, o)
		local a = ANIM[name]
		if not a then return end
		o = o or {}
		local rate = o.rate or 1
		act = {
			name = name, a = a, el = 0, t = 0, rate = rate, loop = o.loop or false, dur = a.L / rate,
			events = o.events, fired = {}, onEnd = o.onEnd, data = o.data,
			fadeIn = o.fadeIn or 0.06, fadeOut = o.fadeOut or 0.1, stopping = false, stopT = 0,
		}
		return act
	end

	local function stopAct()
		if act and not act.stopping then
			act.stopping = true
			act.stopT = act.el
		end
	end

	-- ===== moves =====
	local function dash()
		local look = flat(root.CFrame.LookVector)
		local md = hum.MoveDirection
		local dir = (md.Magnitude > 0.1) and flat(md) or look
		S.dash = { dir = dir, t0 = os.clock() }
	end

	local function endCharge()
		stopAct()
		unlockMove()
		playAct("Stop", { fadeIn = 0.08 })
	end

	local function beginCharge()
		unlockMove()
		playAct("Run", { rate = 1.8, loop = true, data = { charging = true, dir = flat(root.CFrame.LookVector), t0 = os.clock() } })
	end

	local function charge()
		sfx(SFX.attack, root, 0.6)
		lockMove()
		playAct("LeapStart", { rate = 2, events = { { CHARGE_STARTUP, beginCharge } } })
	end

	local function launchLeap()
		unlockMove()
		root.AssemblyLinearVelocity = flat(root.CFrame.LookVector) * LEAP_FORWARD + Vector3.new(0, LEAP_UP, 0)
		sfx(SFX.attack, root, 0.6)
		playAct("Leaping", { loop = true, data = { leaping = true, t0 = os.clock() } })
	end

	local function leap()
		lockMove()
		playAct("LeapStart", { events = { { LEAP_STARTUP, launchLeap } } })
	end

	-- ===== moves as TSB hotbar tools (Custom Weapon library, with a plain Tool fallback) =====
	local function makeMove(name, cooldown, action)
		if weapon then
			local ok, res = pcall(function() return weapon:Create({ name = name, cooldown = cooldown, action = action }) end)
			if ok then return res end
			warn("[dandy-tsb] weapon:Create failed for " .. name .. ": " .. tostring(res))
		end
		local backpack = plr:FindFirstChildOfClass("Backpack") or plr:WaitForChild("Backpack")
		local tool = Instance.new("Tool")
		tool.Name = name
		tool.RequiresHandle = false
		tool.CanBeDropped = false
		local last = 0
		tool.Activated:Connect(function()
			if os.clock() - last >= cooldown then
				last = os.clock()
				task.spawn(action)
			end
		end)
		tool.Parent = backpack
		return tool
	end

	local function setupMoves()
		local backpack = plr:FindFirstChildOfClass("Backpack") or plr:WaitForChild("Backpack")
		for _, move in ipairs(backpack:GetChildren()) do move:Destroy() end -- remove all moves
		makeMove("Dash", CD.Dash, dash)
		makeMove("Charge", CD.Charge, charge)
		makeMove("Leap", CD.Leap, leap)
	end

	-- ===== M1: swap TSB's animation for the Dandy attack =====
	local M1_LOOKUP = {}
	for slot, ids in ipairs(M1_IDS) do
		for _, id in ipairs(ids) do M1_LOOKUP[id] = slot end
	end

	local EMOTE_SET = {}
	for _, id in ipairs(EMOTE_IDS) do EMOTE_SET[id] = true end

	local function isActionPriority(track)
		local p = track.Priority
		return p == Enum.AnimationPriority.Action or p == Enum.AnimationPriority.Action2
			or p == Enum.AnimationPriority.Action3 or p == Enum.AnimationPriority.Action4
	end

	local function looksLikeEmote(track, id)
		if id and EMOTE_SET[id] then return true end
		local nm = string.lower((track.Animation and track.Animation.Name) or "")
		for _, w in ipairs(EMOTE_WORDS) do
			if string.find(nm, w, 1, true) then return true end
		end
		return false
	end

	local function onAnimPlayed(track)
		local idStr = track.Animation and string.match(track.Animation.AnimationId, "%d+")
		local id = idStr and tonumber(idStr)

		-- TSB's block animation drives Dandy's block (the game's animation keeps playing underneath)
		if id == BLOCK_ANIM_ID then
			S.blocking = true
			S.blockTrack = track
			S.blockT = 0
			track.Stopped:Connect(function()
				if S.blockTrack == track then
					S.blocking = false
					S.blockTrack = nil
				end
			end)
			return
		end

		-- M1: swap the game's animation for the Dandy attack
		local slot = id and M1_LOOKUP[id]
		if slot then
			local len = (track.Length and track.Length > 0) and track.Length or M1_DEFAULT_DURATION
			local effective = len / math.max(track.Speed, 0.1)
			track:Stop(0)
			local name = M1_MAP[slot]
			local a = ANIM[name]
			if not a then return end
			sfx(SFX.attack, root, 0.5)
			playAct(name, { rate = math.clamp(a.L / math.max(effective, 0.1), M1_RATE_MIN, M1_RATE_MAX) })
			return
		end

		-- emotes (and, if enabled, any other action animation): pause the custom animations until it is done
		if looksLikeEmote(track, id) or (PAUSE_FOR_ANY_ACTION and isActionPriority(track)) then
			S.foreign[track] = true
			track.Stopped:Connect(function() S.foreign[track] = nil end)
		end
	end

	-- the body leans into strafes and backwards (from the kit's Animate script)
	local function updateBodyLean(dt, moveDir)
		local L = S.body
		local look, right = flat(root.CFrame.LookVector), flat(root.CFrame.RightVector)
		local moving = moveDir.Magnitude > 0.1
		local lookDot, rightDot = 0, 0
		if moving then
			local u = moveDir.Unit
			lookDot, rightDot = look:Dot(u), right:Dot(u)
		end
		local sign, pitch, roll, hip = 1, 0, 0, 0
		if moving then
			if lookDot < -0.5 then sign, pitch = -1, -5 elseif lookDot > 0.5 then sign, pitch = 1, 0 end
			if rightDot > 0.3 then roll, hip = -10, -15 elseif rightDot < -0.3 then roll, hip = 10, 15 end
		end
		local k = math.min(1, dt * 5)
		L.pitch += (pitch - L.pitch) * k
		L.roll += (roll * sign - L.roll) * k
		L.hip += (hip * sign - L.hip) * k
	end

	-- ===== per-frame =====
	-- Stepped (PreSimulation) runs right AFTER the Animator wrote this frame's joint Transforms and BEFORE physics, so what we
	-- write here is what is rendered and replicated. Heartbeat re-applies the same values.
	local function step(dt)
		if not (char and char.Parent and hum and hum.Parent and root and root.Parent) then return end
		dt = math.min(dt, 0.1)
		local now = os.clock()
		local vel = root.AssemblyLinearVelocity
		table.clear(final)

		-- dash push
		local d = S.dash
		if d then
			if now - d.t0 < DASH_TIME then
				root.AssemblyLinearVelocity = d.dir * DASH_SPEED + Vector3.new(0, vel.Y, 0)
			else
				S.dash = nil
			end
		end

		-- charge push (until a wall or the time limit)
		if act and act.data and act.data.charging then
			local c = act.data
			root.AssemblyLinearVelocity = c.dir * CHARGE_SPEED + Vector3.new(0, vel.Y, 0)
			local rp = RaycastParams.new()
			rp.FilterType = Enum.RaycastFilterType.Exclude
			rp.FilterDescendantsInstances = { char }
			local res = workspace:Raycast(root.Position, c.dir * 4.5, rp)
			if (res and res.Instance.CanCollide) or now - c.t0 > CHARGE_MAX then
				root.AssemblyLinearVelocity = Vector3.new(0, vel.Y, 0)
				endCharge()
			end
		end

		-- leap: land when you touch the ground again
		if act and act.data and act.data.leaping and now - act.data.t0 > 0.25 and hum.FloorMaterial ~= Enum.Material.Air then
			playAct("LeapLand", { onEnd = unlockMove })
		end

		-- layers
		local pose, weight = {}, {}
		local function addLayer(anim, t, w)
			if w <= 0.001 then return end
			for key, tr in pairs(anim.tr) do
				local cf = sample(tr, t)
				pose[key] = pose[key] and pose[key]:Lerp(cf, w) or cf
				weight[key] = math.max(weight[key] or 0, w)
			end
		end

		-- emotes / other action animations pause every custom animation until they are done
		for tr in pairs(S.foreign) do
			if not tr.IsPlaying then S.foreign[tr] = nil end
		end
		if S.blockTrack and not S.blockTrack.IsPlaying then
			S.blocking = false
			S.blockTrack = nil
		end
		local paused = next(S.foreign) ~= nil
		S.paused = paused

		-- Dandy's idle / walk (+ the stop-walk tail) replace the game's while you are on the ground and nothing else is playing
		local speed = (vel * Vector3.new(1, 0, 1)).Magnitude
		local grounded = hum.FloorMaterial ~= Enum.Material.Air
		local leaping = act and act.data and act.data.leaping
		local locoOn = DANDY_LOCOMOTION and not paused and (grounded or leaping)
		S.locoW = math.clamp(S.locoW + (locoOn and 1 or -1) * dt / 0.12, 0, 1)
		if S.locoW > 0 then
			local moving = speed > 1
			local loco = moving and ANIM.Run or ANIM.Idle
			local rate = moving and math.clamp(speed / 18, 0.3, 1.6) or 1
			S.locoPhase = (S.locoPhase + dt * rate / loco.L) % 1
			addLayer(loco, S.locoPhase * loco.L, S.locoW)
			if moving then
				S.tail, S.wasMoving = nil, true
			elseif S.wasMoving then
				S.wasMoving = false
				if not act and not S.blocking then S.tail = { t = 0 } end
			end
			if S.tail then
				S.tail.t += dt
				if S.tail.t >= ANIM.Stop.L then S.tail = nil else addLayer(ANIM.Stop, S.tail.t, S.locoW) end
			end
		else
			S.tail = nil
		end

		-- block layer (driven by TSB's block animation; fades in / out)
		S.blockW = math.clamp(S.blockW + ((S.blocking and not paused) and 1 or -1) * dt / 0.12, 0, 1)
		if S.blockW > 0 then
			S.blockT = (S.blockT + dt) % ANIM.Block.L
			addLayer(ANIM.Block, S.blockT, S.blockW)
		end

		-- action layer (its timers keep running while paused, but nothing is applied)
		if act then
			local a = act
			a.el += dt
			a.t += dt * a.rate
			if a.events then
				for i, ev in ipairs(a.events) do
					if not a.fired[i] and a.t >= ev[1] then
						a.fired[i] = true
						ev[2]()
						if act ~= a then break end
					end
				end
			end
			if act == a then
				if a.loop then
					a.t %= a.a.L
					if a.stopping and a.el - a.stopT >= a.fadeOut then act = nil end
				elseif a.el >= a.dur then
					act = nil
					if a.onEnd then a.onEnd() end
				end
			end
			if act == a then
				local w = math.min(1, a.el / a.fadeIn)
				if a.loop then
					if a.stopping then w = w * math.max(0, 1 - (a.el - a.stopT) / a.fadeOut) end
				else
					w = math.min(w, (a.dur - a.el) / a.fadeOut)
				end
				a.w = math.clamp(w, 0, 1)
				if not paused then addLayer(a.a, math.min(a.t, a.a.L), a.w) end
			end
		end

		-- lean into strafes / backwards while Dandy's locomotion is active
		if S.locoW > 0.01 then
			updateBodyLean(dt, hum.MoveDirection)
			local L, w = S.body, S.locoW
			if pose.Torso then pose.Torso = CFrame.Angles(math.rad(L.pitch * w), 0, math.rad(L.roll * w)) * pose.Torso end
			local hipR = CFrame.fromOrientation(0, math.rad(L.hip * w), 0)
			if pose["Left Leg"] then pose["Left Leg"] = hipR * pose["Left Leg"] end
			if pose["Right Leg"] then pose["Right Leg"] = hipR * pose["Right Leg"] end
		end

		-- apply on top of whatever the Animator just wrote
		for key, cf in pairs(pose) do
			local j = joints[key]
			if j and j.Parent then
				local v = j.Transform:Lerp(cf, weight[key])
				j.Transform = v
				final[j] = v
			end
		end
	end

	local function reapply()
		for j, v in pairs(final) do
			if j.Parent then j.Transform = v end
		end
	end

	-- ===== the embedded Dandy model, mirroring your character =====
	local R6_JOINTS = { "Torso", "Head", "Left Arm", "Right Arm", "Left Leg", "Right Leg" }
	local RIG_SCALE, RIG_ROOT_H, CAM_Y = 1.3, 3.9, 1.2     -- Dandy is R6 x1.3

	local function jointsOf(model)
		local j = {}
		for _, d in ipairs(model:GetDescendants()) do
			if d:IsA("Motor6D") and d.Part0 and d.Part1 then j[d.Part1.Name] = d end
		end
		return j
	end

	local function hidePart(d)
		if (d:IsA("BasePart") or d:IsA("Decal")) and hidden[d] == nil then
			hidden[d] = d.Transparency
			d.Transparency = 1
		end
	end

	-- decode the embedded model (base64 -> the bytes of a normal .rbxm file)
	local B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	local function decodeModel()
		local lookup = {}
		for i = 1, 64 do lookup[string.byte(B64, i)] = i - 1 end
		local data = table.concat(MODEL_B64)
		local out, buf, nb = {}, {}, 0
		for i = 1, #data, 4 do
			local a, b, c, d = string.byte(data, i, i + 3)
			local v = lookup[a] * 262144 + lookup[b] * 4096 + (lookup[c] or 0) * 64 + (lookup[d] or 0)
			nb += 1
			buf[nb] = v // 65536
			if c ~= 61 then nb += 1 buf[nb] = (v // 256) % 256 end
			if d ~= 61 then nb += 1 buf[nb] = v % 256 end
			if nb >= 3000 then
				out[#out + 1] = string.char(table.unpack(buf, 1, nb))
				nb = 0
			end
		end
		if nb > 0 then out[#out + 1] = string.char(table.unpack(buf, 1, nb)) end
		return table.concat(out)
	end

	local function objectsFromFile(path)
		local gca = (typeof(getcustomasset) == "function" and getcustomasset) or (typeof(getsynasset) == "function" and getsynasset)
		if not gca then return nil, "this executor has no getcustomasset" end
		local ok, res = pcall(function() return game:GetObjects(gca(path)) end)
		if ok and type(res) == "table" and #res > 0 then return res end
		ok, res = pcall(function() return game:GetObjects(gca(path, true)) end)
		if ok and type(res) == "table" and #res > 0 then return res end
		return nil, "GetObjects failed on " .. path .. ": " .. tostring(res)
	end

	local function loadObjects()
		local ok, custom = pcall(function() return getgenv().DANDY_MODEL end)
		if ok and typeof(custom) == "Instance" then return { custom } end

		local why = "no way to load the model"
		-- 1) the embedded copy
		if typeof(writefile) == "function" then
			local okd, bytes = pcall(decodeModel)
			if okd and #bytes > 100 then
				local out = "slopcode_dandy_v2.rbxm"
				if pcall(writefile, out, bytes) then
					local res, err = objectsFromFile(out)
					if res then return res end
					why = err
				else
					why = "writefile failed"
				end
			else
				why = "could not decode the embedded model"
			end
		else
			why = "this executor has no writefile"
		end
		-- 2) optional: a model file or an asset id you provide yourself
		if typeof(readfile) == "function" and typeof(writefile) == "function" then
			for _, path in ipairs(DANDY_FILES) do
				local okr, data = pcall(readfile, path)
				if okr and type(data) == "string" and #data > 0 then
					pcall(writefile, "slopcode_dandy_user.rbxm", data)
					local res = objectsFromFile("slopcode_dandy_user.rbxm")
					if res then return res end
				end
			end
		end
		if DANDY_ASSET then
			local ok2, res = pcall(function() return game:GetObjects(DANDY_ASSET) end)
			if ok2 and type(res) == "table" then return res end
		end
		return nil, why .. " (you can also set getgenv().DANDY_MODEL to the loaded model)"
	end

	local function findDandy(list)
		local function ok(x) return x:IsA("Model") and x:FindFirstChild("HumanoidRootPart") and x:FindFirstChild("Parts") end
		for _, o in ipairs(list) do
			if ok(o) then return o end
			for _, d in ipairs(o:GetDescendants()) do
				if ok(d) then return d end
			end
		end
	end

	-- replace every (invisible) UnionOperation with a stand-in that keeps its welds / children / look
	local function repointJoints(model, old, new)
		for _, j in ipairs(model:GetDescendants()) do
			if j:IsA("JointInstance") or j:IsA("WeldConstraint") then
				if j.Part0 == old then j.Part0 = new end
				if j.Part1 == old then j.Part1 = new end
			end
		end
	end

	local function rebuildUnions(model)
		local list = {}
		for _, d in ipairs(model:GetDescendants()) do
			if d:IsA("UnionOperation") then list[#list + 1] = d end
		end
		local made = 0
		for _, u in ipairs(list) do
			local proxy
			local spec = UNION_MESHES[u.Name]
			if spec and spec.MeshId then
				local ok, mp = pcall(function()
					return InsertService:CreateMeshPartAsync(spec.MeshId, Enum.CollisionFidelity.Box, Enum.RenderFidelity.Precise)
				end)
				if ok and mp then
					proxy = mp
					pcall(function() proxy.TextureID = spec.TextureID or "" end)
				else
					warn(("[dandy] union '%s': mesh %s failed (%s), using a stand-in shape"):format(u.Name, tostring(spec.MeshId), tostring(mp)))
				end
			end
			local shape = UNION_SHAPES[u.Name] or ((u.Name == "Face") and "Block" or "Ball")
			if not proxy then
				proxy = Instance.new("Part")
				if shape == "Ball" or shape == "Cylinder" then
					local mesh = Instance.new("SpecialMesh")
					mesh.MeshType = (shape == "Ball") and Enum.MeshType.Sphere or Enum.MeshType.Cylinder
					mesh.Parent = proxy
				end
			end
			proxy.Name = u.Name
			for _, prop in ipairs({ "Size", "CFrame", "Color", "Material", "Reflectance", "CastShadow", "CanCollide", "CanTouch", "CanQuery", "Massless", "Anchored" }) do
				pcall(function() proxy[prop] = u[prop] end)
			end
			proxy.Transparency = (shape == "Hide") and 1 or u.Transparency
			if HEAD_PARTS[u.Name] then
				local sz, s = u.Size, HEAD_SCALE
				if PETALS[u.Name] then
					sz = Vector3.new(sz.X * s, sz.Y * s * PETAL_SCALE, sz.Z * s * PETAL_SCALE)
				elseif u.Name == "Face" then
					sz = Vector3.new(sz.X * s * FACE_SCALE, sz.Y * s * FACE_SCALE, sz.Z * s)
				elseif MIDDLE[u.Name] then
					sz = Vector3.new(sz.X * s, sz.Y * s * MIDDLE_TALL, sz.Z * s)
				else
					sz = sz * s
				end
				proxy.Size = sz
			end
			repointJoints(model, u, proxy)
			for _, ch in ipairs(u:GetChildren()) do ch.Parent = proxy end
			proxy.Parent = u.Parent
			u:Destroy()
			made += 1
		end
		-- pull the head's parts closer together by the same factor as their sizes
		if HEAD_SCALE ~= 1 then
			for _, w in ipairs(model:GetDescendants()) do
				if w:IsA("Weld") and w.Part0 and w.Part1 and HEAD_PARTS[w.Part0.Name] and HEAD_PARTS[w.Part1.Name] then
					w.C0 = CFrame.new(w.C0.Position * HEAD_SCALE) * w.C0.Rotation
					w.C1 = CFrame.new(w.C1.Position * HEAD_SCALE) * w.C1.Rotation
				end
			end
		end
		print(("[dandy] unions: %d stand-ins built"):format(made))
	end

	-- re-fetch every MeshPart from its asset id (CreateMeshPartAsync) and swap it in, keeping welds, children and look
	local function rebuildMeshes(model)
		local rebuilt, failed = 0, 0
		local list = {}
		for _, d in ipairs(model:GetDescendants()) do
			if d:IsA("MeshPart") then list[#list + 1] = d end
		end
		for _, mp in ipairs(list) do
			local ov = MESH_OVERRIDES[mp.Name]
			local meshId = (ov and ov.MeshId) or mp.MeshId
			local texId = (ov and ov.TextureID) or mp.TextureID
			local ok, fresh = false, nil
			if meshId ~= "" then
				ok, fresh = pcall(function()
					return InsertService:CreateMeshPartAsync(meshId, Enum.CollisionFidelity.Box, Enum.RenderFidelity.Precise)
				end)
			end
			if ok and fresh then
				fresh.Name = mp.Name
				for _, prop in ipairs({ "Size", "CFrame", "Color", "Material", "Reflectance", "Transparency", "CastShadow", "CanCollide", "CanTouch", "CanQuery", "Massless", "Anchored" }) do
					pcall(function() fresh[prop] = mp[prop] end)
				end
				pcall(function() fresh.TextureID = texId end)
				-- every joint that used the old part now uses the new one
				for _, j in ipairs(model:GetDescendants()) do
					if j:IsA("JointInstance") or j:IsA("WeldConstraint") then
						if j.Part0 == mp then j.Part0 = fresh end
						if j.Part1 == mp then j.Part1 = fresh end
					end
				end
				for _, ch in ipairs(mp:GetChildren()) do ch.Parent = fresh end
				fresh.Parent = mp.Parent
				mp:Destroy()
				rebuilt += 1
			else
				failed += 1
				warn(("[dandy] mesh '%s' (%s) could not be loaded: %s"):format(mp.Name, tostring(meshId), tostring(fresh)))
				-- last resort: poke the property on the original part so the engine tries to fetch it again
				pcall(function() mp.MeshId = meshId end)
				pcall(function() mp.TextureID = texId end)
			end
		end
		print(("[dandy] meshes: %d re-fetched, %d failed"):format(rebuilt, failed))
	end

	local function buildDandy()
		if rig then rig:Destroy() rig = nil rigRoot = nil end
		table.clear(rigJoints)
		local c, r = char, root
		if not (c and r) then return end
		if not dandySrc then
			local list, err = loadObjects()
			dandySrc = list and findDandy(list)
			if not dandySrc then
				warn("[dandy-tsb] model failed to load: " .. tostring(err or "no DandyFighter model found") .. " (the moveset still works without it)")
				return
			end
		end
		local newRig = dandySrc:Clone()
		newRig.Name = "dandy_client"
		for _, d in ipairs(newRig:GetDescendants()) do
			if d:IsA("Humanoid") or d:IsA("Animator") or d:IsA("BaseScript") or d:IsA("Configuration") or d:IsA("ValueBase")
				or d:IsA("Sound") or d:IsA("RemoteEvent") or d:IsA("BindableEvent") or d:IsA("Animation") or d:IsA("Folder") then
				pcall(function() d:Destroy() end)
			end
		end
		-- drop welds that double a Motor6D (they would lock the joint rigid)
		local motorPairs = {}
		for _, d in ipairs(newRig:GetDescendants()) do
			if d:IsA("Motor6D") and d.Part0 and d.Part1 then
				motorPairs[d.Part0] = motorPairs[d.Part0] or {}
				motorPairs[d.Part0][d.Part1] = true
			end
		end
		for _, d in ipairs(newRig:GetDescendants()) do
			if d:IsA("Weld") and d.Part0 and d.Part1 then
				local a, b = motorPairs[d.Part0], motorPairs[d.Part1]
				if (a and a[d.Part1]) or (b and b[d.Part0]) then pcall(function() d:Destroy() end) end
			end
		end
		if REBUILD_UNIONS then rebuildUnions(newRig) end
		if REBUILD_MESHES then rebuildMeshes(newRig) end
		local nroot = newRig:FindFirstChild("HumanoidRootPart")
		if not nroot then newRig:Destroy() return end
		for _, d in ipairs(newRig:GetDescendants()) do
			if d:IsA("BasePart") then
				d.CanCollide, d.CanQuery, d.CanTouch, d.Massless = false, false, false, true
				d.Anchored = (d == nroot)
			end
		end
		local ground
		local leg = c:FindFirstChild("Left Leg")
		ground = r.Size.Y / 2 + (leg and leg.Size.Y or 2) + hum.HipHeight
		offY = RIG_ROOT_H - ground
		nroot.CFrame = r.CFrame * CFrame.new(0, offY, 0)
		newRig.Parent = workspace
		if c ~= char then newRig:Destroy() return end -- you respawned while it was loading
		rig, rigRoot, rigJoints = newRig, nroot, jointsOf(newRig)

		-- hide the real avatar on your screen only, and lift the camera to Dandy's height
		for _, d in ipairs(c:GetDescendants()) do hidePart(d) end
		table.insert(charConns, c.DescendantAdded:Connect(hidePart))
		S.cam = hum.CameraOffset
		hum.CameraOffset = Vector3.new(0, CAM_Y, 0)
	end

	local function blendInto(pose, anim, t, w)
		if w <= 0.001 then return end
		for key, tr in pairs(anim.tr) do
			local cf = sample(tr, t)
			pose[key] = pose[key] and pose[key]:Lerp(cf, w) or cf
		end
	end

	-- PreRender: the model follows your character and copies its joints; the corrupt arm uses the baked animations
	local function updateRig(dt)
		if not (rig and rigRoot and rigRoot.Parent and root and root.Parent) then return end
		dt = math.min(dt, 0.1)
		rigRoot.CFrame = root.CFrame * CFrame.new(0, offY, 0)

		for _, name in ipairs(R6_JOINTS) do
			local rj, real = rigJoints[name], joints[name]
			if rj and real then
				local t = real.Transform
				rj.Transform = CFrame.new(t.Position * RIG_SCALE) * t.Rotation
			end
		end

		local speed = (root.AssemblyLinearVelocity * Vector3.new(1, 0, 1)).Magnitude
		local moving = speed > 1
		local loco = moving and CH.Run or CH.Idle
		S.chainPhase = (S.chainPhase + dt * (moving and math.clamp(speed / 16, 0.4, 1.6) or 1) / loco.L) % 1
		local pose = {}
		blendInto(pose, loco, S.chainPhase * loco.L, 1)
		if S.tail and CH.Stop then blendInto(pose, CH.Stop, math.min(S.tail.t, CH.Stop.L), 1) end
		if S.blockW > 0 and CH.Block then blendInto(pose, CH.Block, S.blockT % CH.Block.L, S.blockW) end
		if act and act.w and CH[act.name] then blendInto(pose, CH[act.name], math.min(act.t, CH[act.name].L), act.w) end
		if S.paused then -- an emote / other animation is playing: let the arm relax
			pose = {}
			for _, key in ipairs({ "Upper", "Lower", "Hand", "Finger1", "Finger2", "Finger3" }) do pose[key] = CFrame.new() end
		end

		-- the corrupt arm leans with your movement (from the kit)
		local md = hum.MoveDirection
		local look = flat(root.CFrame.LookVector)
		local right = flat(root.CFrame.RightVector)
		local pitchT, yawT, sgn = 0, 0, 1
		if md.Magnitude > 0.1 then
			local u = md.Unit
			local ld, rd = look:Dot(u), right:Dot(u)
			if ld < -0.5 then sgn, pitchT = -1, -20 elseif ld > 0.5 then sgn, pitchT = 1, 5 end
			if rd > 0.3 then yawT = 20 elseif rd < -0.3 then yawT = -20 end
		end
		local kk = math.min(1, dt * 5)
		S.lean.pitch += (pitchT - S.lean.pitch) * kk
		S.lean.yaw += (yawT * sgn - S.lean.yaw) * kk
		if pose.Upper then
			pose.Upper = CFrame.fromOrientation(math.rad(S.lean.pitch), math.rad(S.lean.yaw), 0) * pose.Upper
		end

		local k = 1 - math.exp(-dt * 25)
		for key, cf in pairs(pose) do
			local j = rigJoints[key]
			if j then j.Transform = j.Transform:Lerp(cf, k) end
		end
	end

	-- ===== character =====
	local function bindCharacter(c)
		for _, cn in ipairs(charConns) do cn:Disconnect() end
		table.clear(charConns)
		for inst, tr in pairs(hidden) do pcall(function() inst.Transparency = tr end) end
		table.clear(hidden)
		if rig then rig:Destroy() rig = nil rigRoot = nil end
		char = c
		hum = c:WaitForChild("Humanoid")
		root = c:WaitForChild("HumanoidRootPart")
		animator = hum:FindFirstChildOfClass("Animator") or hum:WaitForChild("Animator", 3)
		act, S.blocking, S.blockW, S.dash, S.ws0 = nil, false, 0, nil, nil
		S.locoW, S.tail, S.wasMoving, S.blockTrack, S.paused = 0, nil, false, nil, false
		table.clear(S.foreign)
		table.clear(joints)
		for _, d in ipairs(c:GetDescendants()) do
			if d:IsA("Motor6D") and d.Part1 then joints[d.Part1.Name] = d end
		end
		if hum.RigType ~= Enum.HumanoidRigType.R6 or not joints["Torso"] then
			warn("[dandy-tsb] this character is not R6, the Dandy animations need the six standard R6 joints")
		end
		table.insert(charConns, (animator or hum).AnimationPlayed:Connect(onAnimPlayed))
		task.delay(1.5, setupMoves) -- TSB hands out its own moves on spawn, so replace them afterwards
		task.spawn(buildDandy)
	end

	function m.Init()
		ANIM, CH = compile(DATA), compile(CHAIN)
		local ok, lib = pcall(function() return loadstring(game:HttpGet(WEAPON_LIB))() end)
		if ok and lib then
			weapon = lib
		else
			warn("[dandy-tsb] Custom Weapon library could not be loaded (" .. tostring(lib) .. "), using plain tools instead")
		end
		table.insert(conns, RunService.Stepped:Connect(function(_, dt) step(dt) end))
		table.insert(conns, RunService.Heartbeat:Connect(reapply))
		table.insert(conns, RunService.PreRender:Connect(updateRig))
		table.insert(conns, plr.CharacterAdded:Connect(function(c) task.spawn(bindCharacter, c) end))
		if plr.Character then task.spawn(bindCharacter, plr.Character) end
	end

	function m.Destroy()
		for _, c in ipairs(conns) do c:Disconnect() end
		for _, c in ipairs(charConns) do c:Disconnect() end
		table.clear(conns); table.clear(charConns); table.clear(final)
		unlockMove()
		act = nil
		for inst, tr in pairs(hidden) do pcall(function() inst.Transparency = tr end) end
		table.clear(hidden)
		if hum and hum.Parent and S.cam then hum.CameraOffset = S.cam end
		if rig then rig:Destroy() rig = nil rigRoot = nil end
	end

	return m
end

-- ===== run =====
local env = (typeof(getgenv) == "function" and getgenv()) or _G

if env.DANDYTSB_STOP then pcall(env.DANDYTSB_STOP) end

local inst = build()
task.spawn(inst.Init)

env.DANDYTSB_STOP = function()
	inst.Destroy()
	env.DANDYTSB_STOP = nil
end

pcall(function()
	game:GetService("StarterGui"):SetCore("SendNotification", {
		Title = "SlopCode made this!";
		Text = "Built by SlopCode and Claude";
		Icon = "rbxthumb://type=Asset&id=8000227640&w=150&h=150";
		Duration = 5;
	})
end)
